IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'


def task_func(ip_address):
    try:
        data = json.loads(ip_address.encode())
        ip = data['ip']
        raw_match = re.search(r'"ip"\s*:\s*"((?:[^"\\]|\\.)*)"', ip_address)
        if raw_match:
            raw_ip = raw_match.group(1)
            if re.search(r'\\u[0-9a-fA-F]{4}', raw_ip):
                if not re.fullmatch(IP_REGEX, raw_ip):
                    return 'Invalid IP address received'
        if re.match(IP_REGEX, ip):
            return ip
        return 'Invalid IP address received'
    except Exception as e:
        return str(e)

