import re


def task_func(ip_address):
    invalid = 'Invalid IP address received'
    try:
        response = json.loads(ip_address)
    except (TypeError, ValueError):
        return invalid

    if not isinstance(response, dict):
        return invalid

    address = response.get('ip')
    if not isinstance(address, str):
        return invalid

    octet = r'(?:0|[1-9][0-9]{0,2})'
    if re.fullmatch(octet + r'(?:\.' + octet + r'){3}', address) is None:
        return invalid

    if any(int(part) > 255 for part in address.split('.')):
        return invalid

    return address

