IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'


def task_func(ip_address):
    invalid = 'Invalid IP address received'
    try:
        data = json.loads(ip_address)
    except (TypeError, ValueError, UnicodeDecodeError):
        return invalid

    if not isinstance(ip_address, str) or not isinstance(data, dict):
        return invalid
    if not isinstance(data.get('ip'), str):
        return invalid

    decoder = json.JSONDecoder()
    position = ip_address.index('{') + 1
    raw_ip = ''

    while True:
        while ip_address[position].isspace():
            position += 1
        if ip_address[position] == '}':
            break

        key, position = decoder.raw_decode(ip_address, position)
        while ip_address[position].isspace():
            position += 1
        position += 1
        while ip_address[position].isspace():
            position += 1

        start = position
        value, position = decoder.raw_decode(ip_address, position)
        if key == 'ip':
            raw_ip = ip_address[start:position][1:-1] if isinstance(value, str) else ''

        while ip_address[position].isspace():
            position += 1
        if ip_address[position] == '}':
            break
        position += 1

    if re.fullmatch(IP_REGEX, raw_ip) is None:
        return invalid
    if any(len(part) > 3 or int(part) > 255 for part in raw_ip.split('.')):
        return invalid
    return data['ip']

