from statistics import fmean, pstdev


def task_func(df):
    if not {'id', 'age', 'income'}.issubset(df.columns):
        raise ValueError("DataFrame must contain 'id', 'age', and 'income' columns")

    result = df.copy()
    groups = list(df.groupby('id', sort=False, dropna=False).indices.values())

    for column in ('age', 'income'):
        present = df[column].notna().tolist()
        values = [
            float(value) if valid else float('nan')
            for value, valid in zip(df[column].tolist(), present)
        ]
        standardized = [float('nan')] * len(df)

        for positions in groups:
            valid_positions = [i for i in positions if present[i]]
            if not valid_positions:
                continue
            group_values = [values[i] for i in valid_positions]
            mean = fmean(group_values)
            scale = pstdev(group_values)
            for i in valid_positions:
                standardized[i] = (values[i] - mean) / scale if scale else 0.0

        result[column] = standardized

    return result

