def task_func(df, column_name: str, pattern: str):
    result = df.copy(deep=True)
    regex = re.compile(pattern) if pattern else None

    def reorder_words(value):
        if not isinstance(value, str):
            return value
        words = value.split()
        if regex is None:
            return ' '.join(reversed(words))
        positions = [i for i, word in enumerate(words) if regex.match(word)]
        replacements = [words[i] for i in reversed(positions)]
        for position, word in zip(positions, replacements):
            words[position] = word
        return ' '.join(words)

    result[column_name] = result[column_name].apply(reorder_words)
    return result

