def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    def reverse_all_words(text):
        if not isinstance(text, str):
            return text
        return " ".join(text.split()[::-1])

    def reverse_matched_words(text):
        words = text.split()
        matched_words = [word for word in words if re.search(pattern, word)][::-1]
        new_words = [
            matched_words.pop(0) if re.search(pattern, word) else word
            for word in words
        ]
        return " ".join(new_words)

    new_df = df.copy()
    if not pattern:
        new_df[column_name] = new_df[column_name].apply(reverse_all_words)
        return new_df

    new_df[column_name] = new_df[column_name].apply(reverse_matched_words)
    return new_df

def task_func(array):
    from math import dist

    class Labels(list):
        def tolist(self):
            return list(self)

    class Series(list):
        def tolist(self):
            return list(self)

        @property
        def dtype(self):
            return float if any(isinstance(value, float) for value in self) else int

    class Matrix(list):
        def tolist(self):
            return [list(row) for row in self]

        @property
        def shape(self):
            return len(self), len(self[0]) if self else 0

        def __getitem__(self, key):
            if isinstance(key, tuple):
                row, column = key
                rows = list.__getitem__(self, row)
                if isinstance(row, slice):
                    if isinstance(column, slice):
                        return Matrix([values[column] for values in rows])
                    return Series([values[column] for values in rows])
                return rows[column]
            return list.__getitem__(self, key)

    class Indexer:
        def __init__(self, frame):
            self.frame = frame

        def __getitem__(self, key):
            if isinstance(key, tuple):
                return self.frame.values[key]
            if isinstance(key, slice):
                return DataFrame(self.frame.values[key], self.frame.columns)
            return Series(self.frame.values[key])

    class DataFrame:
        def __init__(self, rows, columns):
            self.values = Matrix([list(row) for row in rows])
            self.columns = Labels(columns)
            self.index = Labels(range(len(rows)))
            self.shape = (len(rows), len(self.columns))
            self.iloc = Indexer(self)
            self.iat = self.iloc

        @property
        def empty(self):
            return 0 in self.shape

        def __len__(self):
            return self.shape[0]

        def __getitem__(self, column):
            position = self.columns.index(column)
            return Series([row[position] for row in self.values])

        def to_numpy(self):
            return Matrix([list(row) for row in self.values])

        def equals(self, other):
            return (
                list(self.columns) == list(other.columns)
                and list(self.index) == list(other.index)
                and self.values.tolist() == other.values.tolist()
            )

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self.values]
            if orient == 'list':
                return {column: self[column].tolist() for column in self.columns}
            if orient == 'dict':
                return {column: dict(zip(self.index, self[column])) for column in self.columns}
            raise ValueError('Unsupported orientation')

    if not isinstance(array, list):
        raise TypeError('Input must be a list of lists containing numbers')
    if any(not isinstance(row, list) for row in array):
        raise TypeError('Each row must be a list')
    if any(not isinstance(value, (int, float)) for row in array for value in row):
        raise TypeError('Each value must be an integer or float')

    width = len(array[0]) if array else 0
    if any(len(row) != width for row in array):
        raise TypeError('All rows must have the same length')

    frame = DataFrame(array, [chr(ord('A') + i) for i in range(width)])
    distances = [[0.0] * len(array) for _ in array]
    for i in range(len(array)):
        for j in range(i + 1, len(array)):
            distance = dist(array[i], array[j])
            distances[i][j] = distance
            distances[j][i] = distance

    return frame, DataFrame(distances, range(len(array)))

