            return value
        words = value.split()
        positions = [i for i, word in enumerate(words) if regex.match(word)]
        reversed_words = [words[i] for i in reversed(positions)]
        for position, word in zip(positions, reversed_words):
            words[position] = word
        return " ".join(words)

    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

