def task_func(df):
    data = {}
    for column in df.columns:
        values = [float(v) for v in df[column].tolist()]
        present = [v for v in values if not math.isnan(v)]
        if not present or all(v == present[0] for v in present):
            data[column] = [float('nan') if math.isnan(v) else 0.0 for v in values]
            continue
        n = len(present)
        mean = math.fsum(present) / n
        variance = math.fsum((v - mean) ** 2 for v in present) / n
        std = math.sqrt(variance)
        if std == 0.0:
            data[column] = [float('nan') if math.isnan(v) else 0.0 for v in values]
        else:
            data[column] = [(v - mean) / std for v in values]
    return type(df)(data, index=df.index, columns=df.columns)

