def task_func(df):
    result = df.copy().astype(float)

    for position in range(len(df.columns)):
        values = [float(value) for value in df.iloc[:, position]]
        valid = [value for value in values if not math.isnan(value)]
        if not valid:
            continue
        if any(not math.isfinite(value) for value in valid):
            raise ValueError("Input contains infinity")

        mean = math.fsum(valid) / len(valid)
        if all(value == valid[0] for value in valid):
            standardized = [math.nan if math.isnan(value) else 0.0 for value in values]
        else:
            variance = math.fsum((value - mean) ** 2 for value in valid) / len(valid)
            scale = math.sqrt(variance)
            standardized = [(value - mean) / scale for value in values]

        result.iloc[:, position] = standardized

    return result

