def task_func(matrix):
    df = pd.DataFrame(matrix).astype(float)
    centered = df - df.mean(axis=0)
    values = [v for row in centered.itertuples(index=False) for v in row if not math.isnan(v)]
    if values:
        pooled_std = math.sqrt(sum(v * v for v in values) / len(values))
    else:
        pooled_std = 0.0
    if pooled_std == 0 or math.isnan(pooled_std):
        normalized = centered * 0.0
    else:
        normalized = centered / pooled_std
    return normalized.fillna(0.0)

