import sys


def task_func(matrix):
    if getattr(matrix, "ndim", 2) != 2:
        raise ValueError("matrix must be two-dimensional")

    rows = [[float(value) for value in row] for row in matrix]
    row_count = len(rows)
    column_count = len(rows[0]) if rows else getattr(matrix, "shape", (0, 0))[1]

    if any(len(row) != column_count for row in rows):
        raise ValueError("matrix must be rectangular")

    dataframe = sys.modules["pandas"].DataFrame
    if row_count == 0 or column_count == 0:
        return dataframe(rows, columns=range(column_count))

    means = [
        math.fsum(row[column] for row in rows) / row_count
        for column in range(column_count)
    ]
    centered = [
        [value - mean for value, mean in zip(row, means)]
        for row in rows
    ]
    pooled = [value for row in centered for value in row]
    pooled_mean = math.fsum(pooled) / len(pooled)
    deviation = math.sqrt(
        math.fsum((value - pooled_mean) ** 2 for value in pooled) / len(pooled)
    )

    normalized = [
        [value / deviation if deviation else float("nan") for value in row]
        for row in centered
    ]
    return dataframe(normalized, columns=range(column_count))

