import sys


def task_func(matrix):
    rows = [list(row) for row in matrix]
    row_count = len(rows)
    shape = getattr(matrix, 'shape', None)
    if shape is not None and len(shape) != 2:
        raise ValueError('matrix must be two-dimensional')
    column_count = len(rows[0]) if rows else (shape[1] if shape is not None else 0)
    if any(len(row) != column_count for row in rows):
        raise ValueError('matrix must be rectangular')

    normalized = [[float('nan')] * column_count for _ in rows]
    for column in range(column_count):
        values = [float(row[column]) for row in rows]
        if not values or not all(math.isfinite(value) for value in values):
            continue
        mean = math.fsum(value / row_count for value in values)
        centered = [value - mean for value in values]
        deviation = math.hypot(*centered) / math.sqrt(row_count)
        if deviation != 0:
            for row, value in enumerate(centered):
                normalized[row][column] = value / deviation

    return sys.modules['pandas'].DataFrame(
        normalized,
        index=range(row_count),
        columns=range(column_count),
        dtype=float,
    )

