def task_func(df):
    import math
    from statistics import NormalDist

    def polynomial(coefficients, x):
        result = 0.0
        for coefficient in reversed(coefficients):
            result = result * x + coefficient
        return result

    def shapiro_pvalue(column):
        values = sorted(float(value) for value in column)
        n = len(values)
        if n < 3 or any(not math.isfinite(value) for value in values):
            return float('nan')
        if values[0] == values[-1]:
            return 1.0

        scale = max(abs(values[0]), abs(values[-1]))
        values = [value / scale for value in values]
        midpoint = values[n // 2]
        values = [value - midpoint for value in values]

        if n == 3:
            weights = [math.sqrt(0.5)]
        else:
            normal = NormalDist()
            raw = [normal.inv_cdf((i + 0.625) / (n + 0.25))
                   for i in range(n // 2)]
            squared_norm = 2.0 * math.fsum(value * value for value in raw)
            norm = math.sqrt(squared_norm)
            inverse_root_n = 1.0 / math.sqrt(n)
            first = polynomial(
                (0.0, 0.221157, -0.147981, -2.07119, 4.434685, -2.706056),
                inverse_root_n,
            ) - raw[0] / norm

            if n > 5:
                second = polynomial(
                    (0.0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633),
                    inverse_root_n,
                ) - raw[1] / norm
                factor = math.sqrt(
                    (squared_norm - 2.0 * raw[0] ** 2 - 2.0 * raw[1] ** 2)
                    / (1.0 - 2.0 * first ** 2 - 2.0 * second ** 2)
                )
                weights = [first, second] + [-value / factor for value in raw[2:]]
            else:
                factor = math.sqrt(
                    (squared_norm - 2.0 * raw[0] ** 2)
                    / (1.0 - 2.0 * first ** 2)
                )
                weights = [first] + [-value / factor for value in raw[1:]]

        mean = math.fsum(values) / n
        variance_sum = math.fsum((value - mean) ** 2 for value in values)
        projection = math.fsum(
            weight * (values[n - 1 - i] - values[i])
            for i, weight in enumerate(weights)
        )
        root_variance = math.sqrt(variance_sum)
        one_minus_w = (
            (root_variance - projection) * (root_variance + projection)
            / variance_sum
        )
        one_minus_w = min(1.0, max(0.0, one_minus_w))

        if n == 3:
            w = max(0.75, 1.0 - one_minus_w)
            return min(1.0, max(0.0, 1.0 - 6.0 / math.pi * math.acos(math.sqrt(w))))
        if one_minus_w == 0.0:
            return 1.0

        y = math.log(one_minus_w)
        if n <= 11:
            gamma = -2.273 + 0.459 * n
            if y >= gamma:
                return 1e-19
            y = -math.log(gamma - y)
            location = polynomial((0.5440, -0.39978, 0.025054, -0.0006714), n)
            spread = math.exp(polynomial((1.3822, -0.77857, 0.062767, -0.0020322), n))
        else:
            log_n = math.log(n)
            location = polynomial((-1.5861, -0.31082, -0.083751, 0.0038915), log_n)
            spread = math.exp(polynomial((-0.4803, -0.082676, 0.0030302), log_n))

        return 0.5 * math.erfc((y - location) / (spread * math.sqrt(2.0)))

    return {
        label: shapiro_pvalue(column)
        for label, column in df.items()
        if getattr(column.dtype, 'kind', None) == 'f'
    }

