    from math import dist, isfinite

    class Series(list):
        def tolist(self):
            return list(self)

        def unique(self):
            return Series(dict.fromkeys(self))

        def nunique(self):
            return len(self.unique())

        def all(self):
            return all(self)

        def any(self):
            return any(self)

        def __eq__(self, other):
            if isinstance(other, (list, tuple)):
                return Series(a == b for a, b in zip(self, other))
            return Series(value == other for value in self)

        def __ne__(self, other):
            return Series(not value for value in self.__eq__(other))

        @property
        def values(self):
            return self

    class DataFrame:
        def __init__(self, rows, columns):
            self._rows = [list(row) for row in rows]
            self.columns = Series(columns)
            self.index = Series(range(len(self._rows)))

        def __len__(self):
            return len(self._rows)

        def __getitem__(self, key):
            if isinstance(key, list):
                positions = [self.columns.index(name) for name in key]
                return DataFrame(
                    [[row[i] for i in positions] for row in self._rows], key
                )
            position = self.columns.index(key)
            return Series(row[position] for row in self._rows)

        @property
        def shape(self):
            return len(self), len(self.columns)

        @property
        def empty(self):
            return not self._rows or not self.columns

        @property
        def values(self):
            return Series(Series(row) for row in self._rows)

        @property
        def iloc(self):
            frame = self

            class Indexer:
                def __getitem__(self, key):
                    if isinstance(key, tuple):
                        row_key, column_key = key
                        if isinstance(row_key, int):
                            result = frame._rows[row_key][column_key]
                            return Series(result) if isinstance(column_key, slice) else result
                        rows = frame._rows[row_key]
                        if isinstance(column_key, int):
                            return Series(row[column_key] for row in rows)
                        return DataFrame(
                            [row[column_key] for row in rows],
                            frame.columns[column_key],
                        )
                    if isinstance(key, int):
                        return Series(frame._rows[key])
                    return DataFrame(frame._rows[key], frame.columns)

            return Indexer()

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self._rows]
            if orient == 'list':
                return {name: self[name].tolist() for name in self.columns}
            if orient == 'dict':
                return {name: dict(enumerate(self[name])) for name in self.columns}
            raise ValueError('Unsupported orientation')

        def __repr__(self):
            lines = ['\t'.join([''] + list(map(str, self.columns)))]
            lines.extend(
                '\t'.join(map(str, [i] + row))
                for i, row in enumerate(self._rows)
            )
            return '\n'.join(lines)

    rows = [list(row) for row in data]
    columns = list(cols)
    if any(len(row) != len(columns) for row in rows):
        raise ValueError('Each row must match the number of columns')
    points = [tuple(float(value) for value in row) for row in rows]
    if any(not isfinite(value) for point in points for value in point):
        raise ValueError('Data must contain finite numeric values')

    neighbors = [[] for _ in points]
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if dist(points[i], points[j]) < 3:
                neighbors[i].append(j)
                neighbors[j].append(i)

    labels = [-1] * len(points)
    cluster = 0
    for start in range(len(points)):
        if labels[start] != -1 or not neighbors[start]:
            continue
        labels[start] = cluster
        pending = [start]
        while pending:
            current = pending.pop()
            for neighbor in neighbors[current]:
                if labels[neighbor] == -1:
                    labels[neighbor] = cluster
                    pending.append(neighbor)
        cluster += 1

    if 'Cluster' in columns:
        position = columns.index('Cluster')
        for row, label in zip(rows, labels):
            row[position] = label
    else:
        columns.append('Cluster')
        for row, label in zip(rows, labels):
            row.append(label)
    return DataFrame(rows, columns)

