import sys


def task_func(df, target):
    if target not in df.columns:
        raise KeyError(target)
    if len(df.columns) < 2:
        raise ValueError('At least one predictor is required.')

    rows = [tuple(float(value) for value in row)
            for row in df.itertuples(index=False, name=None)]
    n = len(rows)
    if n == 0:
        raise ValueError('At least one sample is required.')
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError('All values must be finite.')
    if n < 2:
        return float('nan')

    def dot(a, b):
        return math.fsum(x * y for x, y in zip(a, b))

    columns = []
    for values in zip(*rows):
        mean = math.fsum(values) / n
        columns.append([value - mean for value in values])

    residual = columns.pop()
    total = dot(residual, residual)
    if total == 0.0:
        return 1.0

    scale = max(math.sqrt(dot(column, column)) for column in columns)
    tolerance = sys.float_info.epsilon * max(n, len(columns)) * scale

    while columns:
        pivot = max(range(len(columns)),
                    key=lambda j: dot(columns[j], columns[j]))
        direction = columns.pop(pivot)
        norm = math.sqrt(dot(direction, direction))
        if norm <= tolerance:
            break
        direction = [value / norm for value in direction]

        for vector in [residual] + columns:
            for _ in range(2):
                coefficient = dot(direction, vector)
                for i in range(n):
                    vector[i] -= coefficient * direction[i]

    return float(1.0 - dot(residual, residual) / total)

