def task_func(data, cols):
    rows = [list(row) for row in data]
    columns = list(cols)
    if not rows or not columns:
        raise ValueError('Data must contain at least one row and one feature')
    if any(len(row) != len(columns) for row in rows):
        raise ValueError('Each row must match the number of columns')

    points = [[float(value) for value in row] for row in rows]
    if any(not math.isfinite(value) for point in points for value in point):
        raise ValueError('Data must contain only finite numeric values')

    parents = list(range(len(points)))

    def find(index):
        while parents[index] != index:
            parents[index] = parents[parents[index]]
            index = parents[index]
        return index

    for i, point in enumerate(points):
        for j in range(i):
            if math.dist(point, points[j]) <= 3:
                first, second = find(i), find(j)
                if first != second:
                    parents[first] = second

    sizes = {}
    for i in range(len(points)):
        root = find(i)
        sizes[root] = sizes.get(root, 0) + 1

    cluster_ids = {}
    labels = []
    for i in range(len(points)):
        root = find(i)
        if sizes[root] < 2:
            labels.append(-1)
        else:
            if root not in cluster_ids:
                cluster_ids[root] = len(cluster_ids)
            labels.append(cluster_ids[root])

    if 'Cluster' in columns:
        positions = [i for i, column in enumerate(columns) if column == 'Cluster']
        for row, label in zip(rows, labels):
            for position in positions:
                row[position] = label
    else:
        columns.append('Cluster')
        for row, label in zip(rows, labels):
            row.append(label)

    return DataFrame(rows, columns)

