        vector[0] += math.copysign(1.0, vector[0])
        vector_norm = math.hypot(*vector)
        vector = [value / vector_norm for value in vector]

        for j in range(k, p):
            projection = 2.0 * math.fsum(
                vector[i - k] * x[i][j] for i in range(k, n)
            )
            for i in range(k, n):
                x[i][j] -= projection * vector[i - k]

        projection = 2.0 * math.fsum(
            vector[i - k] * residual[i] for i in range(k, n)
        )
        for i in range(k, n):
            residual[i] -= projection * vector[i - k]
        rank += 1

    unexplained = math.fsum(value * value for value in residual[rank:])
    return float(1.0 - unexplained / total)

