import math


def task_func(list_of_pairs):
    class Series(list):
        def tolist(self):
            return list(self)

        @property
        def values(self):
            return self

        def min(self):
            return min((x for x in self if x == x), default=float('nan'))

        def max(self):
            return max((x for x in self if x == x), default=float('nan'))

        def between(self, left, right):
            return Series(left <= x <= right for x in self)

        def all(self):
            return all(self)

    class DataFrame:
        def __init__(self, categories, values):
            self.Category = Series(categories)
            self.Value = Series(values)
            self.columns = Series(['Category', 'Value'])
            self.index = Series(range(len(values)))

        def __getitem__(self, key):
            if key == 'Category':
                return self.Category
            if key == 'Value':
                return self.Value
            raise KeyError(key)

        def __len__(self):
            return len(self.Value)

        def __iter__(self):
            return iter(self.columns)

        @property
        def shape(self):
            return (len(self), 2)

        @property
        def empty(self):
            return len(self) == 0

        @property
        def values(self):
            return [list(row) for row in zip(self.Category, self.Value)]

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self.values]
            if orient == 'list':
                return {key: self[key].tolist() for key in self.columns}
            if orient == 'dict':
                return {key: dict(enumerate(self[key])) for key in self.columns}
            raise ValueError('Unsupported orientation')

        def __repr__(self):
            rows = ['Category\tValue']
            rows.extend(f'{category}\t{value:.6f}' for category, value in zip(self.Category, self.Value))
            return '\n'.join(rows)

    pairs = list(list_of_pairs)
    if not pairs:
        raise ValueError('Input must not be empty')

    categories = []
    values = []
    for category, value in pairs:
        try:
            number = float(value) if value is not None else float('nan')
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError('Values must be numeric') from exc
        if math.isinf(number):
            raise ValueError('Values must be finite')
        categories.append(category)
        values.append(number)

    finite_values = [value for value in values if not math.isnan(value)]
    if not finite_values:
        return DataFrame(categories, values)

    minimum = min(finite_values)
    maximum = max(finite_values)
    span = maximum - minimum
    denominator = 1.0 if span < 10 * math.ulp(1.0) else span
    scale = 1.0 / denominator
    offset = -minimum * scale
    normalized = [value * scale + offset for value in values]
    return DataFrame(categories, normalized)

