            self._values = list(values)
            self.columns = Series(['Scaled Values'])
            self.index = Series(range(len(self._values)))
            self.shape = (len(self._values), 1)
            self.empty = not self._values
            self.iloc = Indexer(self)

        def __len__(self):
            return len(self._values)

        def __iter__(self):
            return iter(self.columns)

        def __getitem__(self, column):
            if column != 'Scaled Values':
                raise KeyError(column)
            return Series(self._values)

        @property
        def values(self):
            return Series([Series([value]) for value in self._values])

        def to_dict(self, orient='dict'):
            if orient == 'list':
                return {'Scaled Values': list(self._values)}
            if orient == 'records':
                return [{'Scaled Values': value} for value in self._values]
            if orient == 'dict':
                return {'Scaled Values': dict(enumerate(self._values))}
            raise ValueError('Unsupported orientation')

        def __repr__(self):
            lines = ['   Scaled Values']
            lines.extend(f'{i}  {value}' for i, value in enumerate(self._values))
            return '\n'.join(lines)

    values = [float(value) for value in l]
    if not values:
        return DataFrame([])
    minimum = min(values)
    span = max(values) - minimum
    scaled = [(value - minimum) / span for value in values] if span else [0.0] * len(values)
    return DataFrame(scaled)

