import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(P, T):
    P = np.asarray(P)
    T = np.asarray(T)
    if P.ndim != 2 or T.ndim != 3:
        raise ValueError("P must be a matrix and T must be a 3D tensor.")
    if P.size == 0 or T.size == 0:
        raise ValueError("P and T must not be empty.")
    if P.shape[1] != T.shape[0]:
        raise ValueError("P and T have incompatible shapes.")

    product = np.tensordot(P, T, axes=([1], [0]))
    features = product.reshape(P.shape[0], -1).astype(float)
    if not np.isfinite(features).all():
        raise ValueError("The multiplication result must contain only finite values.")

    constant_nonzero = np.all(features == features[0], axis=0) & (features[0] != 0)
    normalized = np.zeros_like(features)
    remaining = ~constant_nonzero
    if remaining.any():
        normalized[:, remaining] = StandardScaler().fit_transform(features[:, remaining])

    columns = [f"feature_{i}" for i in range(features.shape[1])]
    return pd.DataFrame(normalized, columns=columns)

