def task_func(matrix1, matrix2):
    import math
    import numbers

    def read_matrix(matrix):
        shape = getattr(matrix, 'shape', None)
        if shape is not None and len(shape) != 2:
            raise ValueError('Each matrix must be two-dimensional')
        rows = [list(row) for row in matrix]
        width = int(shape[1]) if shape is not None else (len(rows[0]) if rows else 0)
        if any(len(row) != width for row in rows):
            raise ValueError('Each matrix must be rectangular')
        return rows, width

    left, left_width = read_matrix(matrix1)
    right, right_width = read_matrix(matrix2)
    if len(left) != len(right):
        raise ValueError('Matrices must have matching row counts')
    if left_width != right_width:
        raise ValueError('Matrices must have matching column counts')

    rows = [a + b for a, b in zip(left, right)]
    column_count = left_width + right_width
    if not rows or column_count == 0:
        columns = ', '.join(map(str, range(column_count)))
        indices = ', '.join(map(str, range(len(rows))))
        return f'Empty DataFrame\nColumns: [{columns}]\nIndex: [{indices}]'

    use_float = any(
        getattr(getattr(matrix, 'dtype', None), 'kind', '') == 'f'
        for matrix in (matrix1, matrix2)
    ) or any(
        isinstance(value, numbers.Real) and not isinstance(value, numbers.Integral)
        for row in rows for value in row
    )

    def format_column(values):
        if not use_float:
            return [str(value) for value in values]
        values = [float(value) for value in values]
        finite = [abs(value) for value in values if math.isfinite(value)]
        scientific = bool(finite) and (
            any(0 < value < 0.000001 for value in finite)
            or (max(finite) > 1000000 and any(len(f'{value:.6f}') > 12 for value in finite))
        )
        precision = 6
        while precision > 1:
            formatted = [format(value, f'.{precision}{"e" if scientific else "f"}') for value in values if math.isfinite(value)]
            mantissas = [value.split('e')[0] for value in formatted]
            if not mantissas or not all(value.endswith('0') for value in mantissas):
                break
            precision -= 1
        result = []
        for value in values:
            if math.isnan(value):
                result.append('NaN')
            elif math.isinf(value):
                result.append('-inf' if value < 0 else 'inf')
            else:
                result.append(format(value, f'.{precision}{"e" if scientific else "f"}'))
        return result

    columns = [format_column(list(values)) for values in zip(*rows)]
    widths = [max(map(len, column)) for column in columns]
    return '\n'.join(
        ' '.join(column[i].rjust(width) for column, width in zip(columns, widths))
        for i in range(len(rows))
    )

