    column_count = first_width + second_width
    if not rows or not column_count:
        return (
            'Empty DataFrame\nColumns: '
            + str(list(range(column_count)))
            + '\nIndex: '
            + str(list(range(len(rows))))
        )

    floating = any(isinstance(value, float) for row in rows for value in row)
    floating = floating or any(
        getattr(getattr(matrix, 'dtype', None), 'kind', '') == 'f'
        for matrix in (matrix1, matrix2)
    )
    columns = []
    for column in zip(*rows):
        if floating:
            values = [float(value) for value in column]
            finite = [value for value in values if math.isfinite(value)]
            formatted = [format(value, '.6f') for value in values]
            scientific = any(0 < abs(value) < 1e-6 for value in finite)
            scientific = scientific or (
                any(abs(value) > 1e6 for value in finite)
                and max(map(len, formatted)) > 12
            )
            if scientific:
                formatted = [format(value, '.6e') for value in values]
            elif finite:
                while all(text.endswith('0') for text, value in zip(formatted, values) if math.isfinite(value)):
                    formatted = [text[:-1] if math.isfinite(value) else text for text, value in zip(formatted, values)]
                formatted = [text + '0' if text.endswith('.') else text for text in formatted]
            formatted = ['NaN' if math.isnan(value) else text for text, value in zip(formatted, values)]
        else:
            formatted = [str(value) for value in column]
        width = max(map(len, formatted))
        columns.append([text.rjust(width) for text in formatted])

