from math import fsum, isnan, sqrt


def task_func(data, cols, percentage):
    rows = list(data)
    if any(len(row) != len(cols) for row in rows):
        raise ValueError('Each row must match the number of columns')

    result = []
    for i, j in combinations(range(len(cols)), 2):
        pairs = []
        for row in rows:
            if row[i] is None or row[j] is None:
                continue
            x, y = float(row[i]), float(row[j])
            if not isnan(x) and not isnan(y):
                pairs.append((x, y))

        if len(pairs) < 2:
            continue

        mean_x = fsum(x for x, _ in pairs) / len(pairs)
        mean_y = fsum(y for _, y in pairs) / len(pairs)
        dx = [x - mean_x for x, _ in pairs]
        dy = [y - mean_y for _, y in pairs]
        variance_x = fsum(x * x for x in dx)
        variance_y = fsum(y * y for y in dy)
        if variance_x == 0 or variance_y == 0:
            continue

        covariance = fsum(x * y for x, y in zip(dx, dy))
        correlation = covariance / sqrt(variance_x * variance_y)
        if abs(correlation) >= percentage:
            result.append((cols[i], cols[j]))

    return result

import math
import operator


def task_func(tuples_list, n_components):
    data = [list(map(float, row)) for row in tuples_list]
    if not data or not data[0]:
        raise ValueError("Input must be a nonempty rectangular matrix")

    rows, columns = len(data), len(data[0])
    if any(len(row) != columns for row in data):
        raise ValueError("All rows must have the same length")
    if any(not math.isfinite(value) for row in data for value in row):
        raise ValueError("Input values must be finite")

    count = min(rows, columns)
    if n_components is None:
        n_components = count
    else:
        n_components = operator.index(n_components)
    if not 0 <= n_components <= count:
        raise ValueError("Invalid number of components")

    means = [math.fsum(row[j] for row in data) / rows for j in range(columns)]
    centered = [[row[j] - means[j] for j in range(columns)] for row in data]
    scale = max(abs(value) for row in centered for value in row)
    if scale == 0 or n_components == 0:
        return [[0.0] * n_components for _ in range(rows)]

    transposed = rows < columns
    if transposed:
        vectors = [[value / scale for value in row] for row in centered]
    else:
        vectors = [[centered[i][j] / scale for i in range(rows)]
                   for j in range(columns)]

    basis = [[float(i == j) for i in range(count)] for j in range(count)]
    for _ in range(100):
        changed = False
        for p in range(count - 1):
            for q in range(p + 1, count):
                a, b = vectors[p], vectors[q]
                alpha = math.fsum(x * x for x in a)
                beta = math.fsum(x * x for x in b)
                gamma = math.fsum(x * y for x, y in zip(a, b))
                if abs(gamma) <= 1e-15 * math.sqrt(alpha) * math.sqrt(beta):
                    continue
                tau = (beta - alpha) / (2.0 * gamma)
                tangent = math.copysign(1.0, tau) / (abs(tau) + math.hypot(1.0, tau))
                cosine = 1.0 / math.hypot(1.0, tangent)
                sine = cosine * tangent
                vectors[p] = [cosine * x - sine * y for x, y in zip(a, b)]
                vectors[q] = [sine * x + cosine * y for x, y in zip(a, b)]
                if transposed:
                    a, b = basis[p], basis[q]
                    basis[p] = [cosine * x - sine * y for x, y in zip(a, b)]
                    basis[q] = [sine * x + cosine * y for x, y in zip(a, b)]
                changed = True
        if not changed:
            break

    singular_values = [math.hypot(*vector) for vector in vectors]
    order = sorted(range(count), key=lambda j: singular_values[j], reverse=True)
    result = [[] for _ in range(rows)]
    for j in order[:n_components]:
        if transposed:
            scores = [value * singular_values[j] for value in basis[j]]
        else:
            scores = vectors[j]
        pivot = max(range(rows), key=lambda i: abs(scores[i]))
        factor = -scale if scores[pivot] < 0 else scale
        for i in range(rows):
            result[i].append(scores[i] * factor)
    return result

