    words2 = re.findall(r'\b\w+\b', text2)
    differences = [len(a) - len(b) for a, b in zip(words1, words2)]
    n = len(differences)
    if n < 2:
        return math.nan, math.nan

    mean = math.fsum(differences) / n
    squared_deviations = math.fsum((d - mean) ** 2 for d in differences)
    if squared_deviations == 0:
        if mean == 0:
            return math.nan, math.nan
        return math.copysign(math.inf, mean), 0.0

    statistic = mean / math.sqrt(squared_deviations / (n * (n - 1)))
    degrees = n - 1
    x = degrees / (degrees + statistic * statistic)

    def continued_fraction(a, b, z):
        tiny = 1e-300
        c = 1.0
        d = 1.0 - (a + b) * z / (a + 1.0)
        if abs(d) < tiny:
            d = tiny
        d = 1.0 / d
        result = d
        for m in range(1, 10001):
            coefficients = (
                m * (b - m) * z / ((a + 2 * m - 1) * (a + 2 * m)),
                -(a + m) * (a + b + m) * z
                / ((a + 2 * m) * (a + 2 * m + 1)),
            )
            for coefficient in coefficients:
                d = 1.0 + coefficient * d
                c = 1.0 + coefficient / c
                if abs(d) < tiny:
                    d = tiny
                if abs(c) < tiny:
                    c = tiny
                d = 1.0 / d
                change = d * c
                result *= change
            if abs(change - 1.0) < 3e-14:
                break
        return result

    if x <= 0.0:
        return statistic, 0.0
    if x >= 1.0:
        return statistic, 1.0

    a = degrees / 2.0
    b = 0.5
    factor = math.exp(
        math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
        + a * math.log(x) + b * math.log1p(-x)
    )
    if x < (a + 1.0) / (a + b + 2.0):
        probability = factor * continued_fraction(a, b, x) / a
    else:
        probability = 1.0 - factor * continued_fraction(b, a, 1.0 - x) / b
    return statistic, min(1.0, max(0.0, probability))

