        return result

    scale = max(abs(data[0]), abs(data[-1]))
    data = [value / scale for value in data]
    midpoint = data[n // 2]
    data = [value - midpoint for value in data]
    mean = math.fsum(data) / n
    denominator = math.fsum((value - mean) ** 2 for value in data)

    if n == 3:
        weights = [math.sqrt(0.5)]
    else:
        normal = NormalDist()
        weights = [normal.inv_cdf((i + 0.625) / (n + 0.25)) for i in range(n // 2)]
        squared_sum = 2.0 * math.fsum(weight * weight for weight in weights)
        root_sum = math.sqrt(squared_sum)
        inverse_root_n = 1.0 / math.sqrt(n)
        first = polynomial((0.0, 0.221157, -0.147981, -2.071190, 4.434685, -2.706056), inverse_root_n) - weights[0] / root_sum
        if n > 5:
            second = polynomial((0.0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633), inverse_root_n) - weights[1] / root_sum
            factor = math.sqrt((squared_sum - 2.0 * weights[0] ** 2 - 2.0 * weights[1] ** 2) / (1.0 - 2.0 * first ** 2 - 2.0 * second ** 2))
            weights[0], weights[1] = first, second
