        else:
            factor = math.sqrt((squared_sum - 2.0 * weights[0] ** 2) / (1.0 - 2.0 * first ** 2))
            weights[0] = first
            start = 1
        for i in range(start, len(weights)):
            weights[i] /= -factor

    numerator = math.fsum(weight * (data[n - 1 - i] - data[i]) for i, weight in enumerate(weights))
    w = min(1.0, max(0.0, numerator * numerator / denominator))

    if n == 3:
        p_value = max(0.0, min(1.0, 1.0 - 6.0 / math.pi * math.acos(math.sqrt(w))))
    elif w == 1.0:
        p_value = 1.0
    else:
        y = math.log1p(-w)
        if n <= 11:
            gamma = -2.273 + 0.459 * n
            if y >= gamma:
                return bool(1e-99 > alpha)
            y = -math.log(gamma - y)
            location = polynomial((0.5440, -0.39978, 0.025054, -0.0006714), n)
