        root_sum = math.sqrt(sum_squares)
        inverse_root_n = 1.0 / math.sqrt(n)
        first = polynomial(
            (0.0, 0.221157, -0.147981, -2.071190, 4.434685, -2.706056),
            inverse_root_n,
        ) - expected[0] / root_sum
        if n > 5:
            second = polynomial(
                (0.0, 0.042981, -0.293762, -1.752461, 5.682633, -3.582633),
                inverse_root_n,
            ) - expected[1] / root_sum
            factor = math.sqrt(
                (sum_squares - 2.0 * expected[0] ** 2 - 2.0 * expected[1] ** 2)
                / (1.0 - 2.0 * first ** 2 - 2.0 * second ** 2)
            )
            weights = [first, second]
            start = 2
        else:
            factor = math.sqrt(
                (sum_squares - 2.0 * expected[0] ** 2)
                / (1.0 - 2.0 * first ** 2)
            )
            weights = [first]
            start = 1
        weights.extend(-expected[i] / factor for i in range(start, half))

    scale = max(abs(values[0]), abs(values[-1]))
    values = [value / scale for value in values]
    origin = values[n // 2]
    values = [value - origin for value in values]
    mean = math.fsum(values) / n
    variance_sum = math.fsum((value - mean) ** 2 for value in values)
    weighted_sum = math.fsum(
        weights[i] * (values[n - 1 - i] - values[i])
        for i in range(half)
    )
    w = min(1.0, max(0.0, weighted_sum ** 2 / variance_sum))

    if n == 3:
        p_value = max(0.0, min(1.0, 1.0 - 6.0 / math.pi * math.acos(math.sqrt(w))))
    elif w >= 1.0:
        p_value = 1.0
    else:
        y = math.log1p(-w)
        if n <= 11:
            gamma = -2.273 + 0.459 * n
            if y >= gamma:
                return bool(1e-19 > alpha)
            y = -math.log(gamma - y)
            mu = polynomial((0.5440, -0.39978, 0.025054, -0.0006714), n)
            sigma = math.exp(polynomial((1.3822, -0.77857, 0.062767, -0.0020322), n))
        else:
