def task_func(text1, text2):
    words1 = re.findall(r'\b\w+\b', text1)
    words2 = re.findall(r'\b\w+\b', text2)
    n = len(words1)
    if n != len(words2) or n < 2:
        return float('nan'), float('nan')

    differences = [len(a) - len(b) for a, b in zip(words1, words2)]
    mean = math.fsum(differences) / n
    variance = math.fsum((d - mean) ** 2 for d in differences) / (n - 1)
    if variance == 0:
        if mean == 0:
            return float('nan'), float('nan')
        return math.copysign(float('inf'), mean), 0.0

    statistic = mean / math.sqrt(variance / n)
    if statistic == 0:
        return 0.0, 1.0

    def continued_fraction(a, b, x):
        tiny = 1e-300

        def nonzero(value):
            return value if abs(value) >= tiny else math.copysign(tiny, value)

        c = 1.0
        d = 1.0 / nonzero(1.0 - (a + b) * x / (a + 1.0))
        result = d
        for m in range(1, 1001):
            coefficient = m * (b - m) * x / ((a + 2 * m - 1) * (a + 2 * m))
            d = 1.0 / nonzero(1.0 + coefficient * d)
            c = nonzero(1.0 + coefficient / c)
            result *= d * c
            coefficient = -(a + m) * (a + b + m) * x / ((a + 2 * m) * (a + 2 * m + 1))
            d = 1.0 / nonzero(1.0 + coefficient * d)
            c = nonzero(1.0 + coefficient / c)
            delta = d * c
            result *= delta
            if abs(delta - 1.0) < 3e-14:
                break
        return result

    df = n - 1
    x = df / (df + statistic * statistic)
    if x <= 0.0:
        return statistic, 0.0
    if x >= 1.0:
        return statistic, 1.0

    a, b = df / 2.0, 0.5
    factor = math.exp(math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
                      + a * math.log(x) + b * math.log1p(-x))
    if x < (a + 1.0) / (a + b + 2.0):
        p_value = factor * continued_fraction(a, b, x) / a
    else:
        p_value = 1.0 - factor * continued_fraction(b, a, 1.0 - x) / b
    return statistic, min(1.0, max(0.0, p_value))

