def task_func(data, n_clusters):
    n_clusters = operator.index(n_clusters)
    if n_clusters < 1:
        raise ValueError('n_clusters must be positive')

    try:
        rows = [tuple(float(value) for value in row) for row in data]
    except (TypeError, ValueError) as exc:
        raise ValueError('data must be a 2D numeric array') from exc

    if not rows or not rows[0]:
        raise ValueError('data must be nonempty')
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError('all rows must have the same length')
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError('data must contain only finite values')
    if n_clusters > len(rows):
        raise ValueError('n_clusters cannot exceed the number of rows')

    def squared_distance(left, right):
        return sum((a - b) ** 2 for a, b in zip(left, right))

    rng = random.Random(0)
    best_labels = None
    best_inertia = math.inf

    for _ in range(10):
        chosen = [rng.randrange(len(rows))]
        centers = [rows[chosen[0]]]
        distances = [squared_distance(row, centers[0]) for row in rows]

        while len(centers) < n_clusters:
            total = sum(distances)
            if total == 0:
                selected = next(i for i in range(len(rows)) if i not in chosen)
            else:
                threshold = rng.random() * total
                cumulative = 0.0
                selected = max(range(len(rows)), key=distances.__getitem__)
                for i, distance in enumerate(distances):
                    cumulative += distance
                    if cumulative > threshold:
                        selected = i
                        break
            chosen.append(selected)
            centers.append(rows[selected])
            distances = [
                min(distance, squared_distance(row, centers[-1]))
                for row, distance in zip(rows, distances)
            ]

        previous_labels = None
        for _ in range(300):
            labels = [
                min(range(n_clusters), key=lambda c: squared_distance(row, centers[c]))
                for row in rows
            ]
            if labels == previous_labels:
                break
            previous_labels = labels
            groups = [[] for _ in range(n_clusters)]
            for index, label in enumerate(labels):
                groups[label].append(index)
            centers = [
                tuple(
                    sum(rows[index][column] for index in group) / len(group)
                    for column in range(width)
                ) if group else centers[label]
                for label, group in enumerate(groups)
            ]

        labels = [
            min(range(n_clusters), key=lambda c: squared_distance(row, centers[c]))
            for row in rows
        ]
        inertia = sum(
            squared_distance(row, centers[label])
            for row, label in zip(rows, labels)
        )
        if best_labels is None or inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    clusters = {label: [] for label in range(n_clusters)}
    for index, label in enumerate(best_labels):
        clusters[label].append(index)
    return clusters

def task_func(data, n_clusters):
    import math
    import operator
    import random

    n_clusters = operator.index(n_clusters)
    rows = [tuple(float(value) for value in row) for row in data]
    if not rows or not rows[0]:
        raise ValueError('data must be a nonempty 2D numeric array')
    width = len(rows[0])
    if any(len(row) != width for row in rows):
        raise ValueError('data must be rectangular')
    if any(not math.isfinite(value) for row in rows for value in row):
        raise ValueError('data must contain only finite values')
    if not 1 <= n_clusters <= len(rows):
        raise ValueError('n_clusters must be between 1 and the number of rows')
    rows.sort()

    def distance_squared(left, right):
        return sum((a - b) ** 2 for a, b in zip(left, right))

    def assign(centers):
        return [
            min(range(n_clusters), key=lambda label: distance_squared(row, centers[label]))
            for row in rows
        ]

    rng = random.Random(0)
    best_labels = None
    best_inertia = math.inf

    for _ in range(20):
        centers = [rows[rng.randrange(len(rows))]]
        nearest = [distance_squared(row, centers[0]) for row in rows]
        while len(centers) < n_clusters:
            total = sum(nearest)
            if total == 0:
                centers.append(rows[rng.randrange(len(rows))])
            else:
                threshold = rng.random() * total
                chosen = len(rows) - 1
                for index, weight in enumerate(nearest):
                    threshold -= weight
                    if threshold < 0:
                        chosen = index
                        break
                centers.append(rows[chosen])
            nearest = [
                min(previous, distance_squared(row, centers[-1]))
                for row, previous in zip(rows, nearest)
            ]

        previous_labels = None
        for _ in range(300):
            labels = assign(centers)
            if labels == previous_labels:
                break
            previous_labels = labels[:]
            members = [[] for _ in range(n_clusters)]
            for index, label in enumerate(labels):
                members[label].append(index)
            for label, group in enumerate(members):
                if not group:
                    candidates = [
                        index for index, owner in enumerate(labels)
                        if len(members[owner]) > 1
                    ]
                    if candidates:
                        index = max(
                            candidates,
                            key=lambda i: distance_squared(rows[i], centers[labels[i]])
                        )
                        if distance_squared(rows[index], centers[labels[index]]) > 0:
                            members[labels[index]].remove(index)
                            labels[index] = label
                            group.append(index)
            centers = [
                tuple(sum(rows[index][axis] for index in group) / len(group)
                      for axis in range(width)) if group else centers[label]
                for label, group in enumerate(members)
            ]

        labels = assign(centers)
        inertia = sum(
            distance_squared(row, centers[label])
            for row, label in zip(rows, labels)
        )
        if best_labels is None or inertia < best_inertia:
            best_inertia = inertia
            best_labels = labels

    clusters = {}
    for index, label in enumerate(best_labels):
        clusters.setdefault(label, []).append(index)
    return clusters

