                raise KeyError(key)
            position = self.columns.index(key)
            return Series(row[position] for row in self.values)

        def to_numpy(self):
            return Matrix([list(row) for row in self.values])

        def to_dict(self, orient='dict'):
            if orient == 'records':
                return [dict(zip(self.columns, row)) for row in self.values]
            if orient == 'list':
                return {key: self[key].tolist() for key in self.columns}
            if orient == 'dict':
                return {key: dict(enumerate(self[key])) for key in self.columns}
            if orient == 'split':
                return {
                    'index': self.index.tolist(),
                    'columns': self.columns.tolist(),
                    'data': self.values.tolist(),
                }
            raise ValueError('Unsupported orientation: ' + str(orient))

        def __repr__(self):
