            cells = [[str(i)] + [str(value) for value in row]
                     for i, row in enumerate(self.values)]
            headers = [''] + self.columns.tolist()
            widths = [max(len(row[j]) for row in [headers] + cells)
                      for j in range(4)]
            return '\n'.join(
                '  '.join(cell.rjust(width) for cell, width in zip(row, widths))
                for row in [headers] + cells
            )

