def task_func(area_string, data=DATA):
    areas = sorted(float(value.replace(",", "")) for value in data["Area_String"])
    prices = sorted(float(value) for value in data["Price"])
    if not areas or len(areas) != len(prices):
        raise ValueError("Areas and prices must have equal, nonzero lengths.")

    area = float(area_string.replace(",", ""))
    mean_area = fsum(areas) / len(areas)
    mean_price = fsum(prices) / len(prices)
