import math


def task_func(data):
    score_strings = data['Score_String']
    grades = data['Grade']
    n = len(score_strings)

    if n != len(grades):
        raise ValueError('Scores and grades must have the same length.')
    if n < 2:
        return float('nan')

    scores = [float(score) for score in score_strings]
    if any(not math.isfinite(score) for score in scores):
        return float('nan')

    grade_codes = {grade: index for index, grade in enumerate(sorted(set(grades)))}
    encoded_grades = [grade_codes[grade] for grade in grades]

    scale = max(abs(score) for score in scores)
    if scale == 0:
        return float('nan')
    scores = [score / scale for score in scores]

    score_mean = math.fsum(scores) / n
    grade_mean = math.fsum(encoded_grades) / n
    score_deviations = [score - score_mean for score in scores]
    grade_deviations = [grade - grade_mean for grade in encoded_grades]

    score_norm = math.hypot(*score_deviations)
    grade_norm = math.hypot(*grade_deviations)
    if score_norm == 0 or grade_norm == 0:
        return float('nan')

    correlation = math.fsum(
        (score / score_norm) * (grade / grade_norm)
        for score, grade in zip(score_deviations, grade_deviations)
    )
    return max(-1.0, min(1.0, correlation))

import math


def task_func(data):
    scores = list(data['Score_String'])
    grades = list(data['Grade'])
    n = len(scores)

    if n != len(grades):
        raise ValueError('Scores and grades must have the same length.')
    if n == 1:
        raise ValueError('Pearson correlation requires at least two observations.')
    if n == 0:
        return float('nan')

    scores = [float(score) for score in scores]
    if any(not math.isfinite(score) for score in scores):
        return float('nan')

    categories = sorted(set(grades))
    encoding = {grade: rank for rank, grade in enumerate(categories)}
    ranks = [encoding[grade] for grade in grades]

    scale = max(abs(score) for score in scores)
    if scale == 0 or len(categories) < 2:
        return float('nan')

    scores = [score / scale for score in scores]
    score_mean = math.fsum(scores) / n
    rank_mean = math.fsum(ranks) / n
    x = [score - score_mean for score in scores]
    y = [rank - rank_mean for rank in ranks]
    x_norm = math.hypot(*x)
    y_norm = math.hypot(*y)

    if x_norm == 0 or y_norm == 0:
        return float('nan')

    correlation = math.fsum((a / x_norm) * (b / y_norm) for a, b in zip(x, y))
    return max(-1.0, min(1.0, correlation))

