import re
from collections import Counter


def task_func(texts):
    documents = []
    for text in texts:
        cleaned = re.sub(r'https?://\S+|www\.\S+', '', text, flags=re.IGNORECASE)
        if cleaned.strip():
            documents.append(cleaned)

    if not documents:
        return [], []

    counts = [Counter(re.findall(r'\b\w\w+\b', text.lower())) for text in documents]
    document_frequencies = Counter()
    for count in counts:
        document_frequencies.update(count.keys())

    features = sorted(document_frequencies)
    if not features:
        raise ValueError('empty vocabulary; perhaps the documents only contain stop words')

    document_count = len(documents)
    idf = {
        word: math.log((1 + document_count) / (1 + document_frequencies[word])) + 1
        for word in features
    }

    scores = []
    for count in counts:
        row = [count[word] * idf[word] for word in features]
        norm = math.sqrt(sum(value * value for value in row))
        scores.append(tuple(round(value / norm, 8) if norm else 0.0 for value in row))

    return scores, features

