def task_func(df):
    if not (hasattr(df, "columns") and hasattr(df, "iloc")):
        raise ValueError("Input must be a DataFrame.")
    columns = list(df.columns)
    if not columns:
        raise ValueError("DataFrame has no columns.")

    if all(isinstance(c, numbers.Integral) and not isinstance(c, bool) for c in columns):
        position = max(range(len(columns)), key=lambda i: int(columns[i]))
    else:
        position = len(columns) - 1

    values = [float(v) for v in df.iloc[:, position].tolist()]
    n = len(values)
    if n == 0 or any(math.isnan(v) for v in values):
        return float("nan")

    mean = math.fsum(values) / n
    deviations = [v - mean for v in values]
    m2 = math.fsum(d * d for d in deviations) / n
    m3 = math.fsum(d * d * d for d in deviations) / n
    if m2 <= (1e-14 * abs(mean)) ** 2 or m2 == 0:
        return float("nan")
    return float(m3 / m2 ** 1.5)

