def task_func(matrix1, matrix2):
    def to_rows(matrix):
        data = matrix.tolist() if hasattr(matrix, 'tolist') else matrix
        rows = [list(row) for row in data]
        if any(not isinstance(row, list) for row in data) if data else False:
            raise ValueError('Inputs must be 2D matrices')
        return rows

    rows1 = to_rows(matrix1)
    rows2 = to_rows(matrix2)

    if len(rows1) != len(rows2):
        raise ValueError('Matrices must have the same number of rows')

    combined = [r1 + r2 for r1, r2 in zip(rows1, rows2)]
    if not combined:
        return ''

    n_cols = max(len(row) for row in combined)
    for row in combined:
        if len(row) != n_cols:
            raise ValueError('Matrix rows must have consistent lengths')

    def format_column(values):
        is_float = all(isinstance(v, float) for v in values)
        if is_float:
            decimals = 1
            for v in values:
                text = repr(v)
                if '.' in text and 'e' not in text.lower():
                    decimals = max(decimals, len(text.split('.')[1]))
            decimals = min(decimals, 6)
            return [format(v, '.{}f'.format(decimals)) for v in values]
        return [str(v) for v in values]

    columns = [format_column([row[c] for row in combined]) for c in range(n_cols)]
    widths = [max(len(text) for text in col) for col in columns]

    lines = []
    for r in range(len(combined)):
        cells = [columns[c][r].rjust(widths[c]) for c in range(n_cols)]
        lines.append(' ' + ' '.join(cells))
    return '\n'.join(lines)

