import re
import math


def task_func(text1, text2):
    def betacf(a, b, x):
        max_iter = 10000
        eps = 1e-16
        fpmin = 1e-300
        qab = a + b
        qap = a + 1.0
        qam = a - 1.0
        c = 1.0
        d = 1.0 - qab * x / qap
        if abs(d) < fpmin:
            d = fpmin
        d = 1.0 / d
        h = d
        for m in range(1, max_iter + 1):
            m2 = 2 * m
            aa = m * (b - m) * x / ((qam + m2) * (a + m2))
            d = 1.0 + aa * d
            if abs(d) < fpmin:
                d = fpmin
            c = 1.0 + aa / c
            if abs(c) < fpmin:
                c = fpmin
            d = 1.0 / d
            h *= d * c
            aa = -(a + m) * (qab + m) * x / ((a + m2) * (qap + m2))
            d = 1.0 + aa * d
            if abs(d) < fpmin:
                d = fpmin
            c = 1.0 + aa / c
            if abs(c) < fpmin:
                c = fpmin
            d = 1.0 / d
            delta = d * c
            h *= delta
            if abs(delta - 1.0) < eps:
                break
        return h

    def betai(a, b, x):
        if x <= 0.0:
            return 0.0
        if x >= 1.0:
            return 1.0
        bt = math.exp(
            math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b)
            + a * math.log(x) + b * math.log(1.0 - x)
        )
        if x < (a + 1.0) / (a + b + 2.0):
            return bt * betacf(a, b, x) / a
        return 1.0 - bt * betacf(b, a, 1.0 - x) / b

    words1 = re.findall(r'\b\w+\b', text1)
    words2 = re.findall(r'\b\w+\b', text2)

    if len(words1) != len(words2):
        return (float('nan'), float('nan'))

    n = len(words1)
    if n < 2:
        return (float('nan'), float('nan'))

    diffs = [len(w1) - len(w2) for w1, w2 in zip(words1, words2)]
    mean = sum(diffs) / n
    variance = sum((d - mean) ** 2 for d in diffs) / (n - 1)
    std = math.sqrt(variance)

    if std == 0.0:
        if mean == 0.0:
            return (float('nan'), float('nan'))
        return (math.copysign(float('inf'), mean), 0.0)

    t_statistic = mean / (std / math.sqrt(n))
    df = n - 1
    x = df / (df + t_statistic ** 2)
    p_value = betai(df / 2.0, 0.5, x)
    p_value = min(max(p_value, 0.0), 1.0)

    return (t_statistic, p_value)

