import re
import string


def task_func(text1, text2):
    pattern = re.compile(
        r"(?<=[A-Za-z0-9])-(?=[A-Za-z0-9])|[" + re.escape(string.punctuation) + r"]"
    )

    def replace(match):
        return " " if match.group(0) == "-" and match.start() > 0 and _is_between_alnum(match) else ""

    def _is_between_alnum(match):
        s = match.string
        i = match.start()
        alnum = string.ascii_letters + string.digits
        return 0 < i < len(s) - 1 and s[i - 1] in alnum and s[i + 1] in alnum

    def clean(text):
        return pattern.sub(replace, text)

    return clean(text1), clean(text2)

