from datetime import time

def task_func(logs: list):
    error_times = []
    for log in logs:
        if "ERROR" in log:
            time_match = re.search(r'(\d{2}):(\d{2}):\d{2}', log)
            if time_match:
                hour, minute = map(int, time_match.groups())
                error_times.append(time(hour, minute))

    distinct_times = set(error_times)
    if distinct_times:
        total_minutes = sum(t.hour * 60 + t.minute for t in distinct_times)
        avg_minutes = total_minutes // len(distinct_times)
        avg_time = time(avg_minutes // 60, avg_minutes % 60)
    else:
        avg_time = time(0, 0)

    return error_times, avg_time

