    mean_y = sum(prices) / n

    sxx = sum((x - mean_x) ** 2 for x in areas)
    sxy = sum((x - mean_x) * (y - mean_y) for x, y in zip(areas, prices))

    slope = sxy / sxx if sxx != 0 else 0.0
    intercept = mean_y - slope * mean_x

    return float(intercept + slope * to_number(area_string))

import math


def task_func(data):
    scores = [float(s) for s in data['Score_String']]
    grades = list(data['Grade'])

    if len(scores) != len(grades):
        raise ValueError("'Score_String' and 'Grade' must have the same length.")

    n = len(scores)
    if n == 1:
        raise ValueError("Pearson correlation requires at least two observations.")
    if n < 2:
        return float('nan')

    categories = sorted(set(grades))
    codes = {grade: index for index, grade in enumerate(categories)}
    encoded = [float(codes[g]) for g in grades]

    mean_x = sum(scores) / n
    mean_y = sum(encoded) / n
    dx = [x - mean_x for x in scores]
    dy = [y - mean_y for y in encoded]

    cov = sum(a * b for a, b in zip(dx, dy))
    var_x = sum(a * a for a in dx)
    var_y = sum(b * b for b in dy)

    if var_x == 0 or var_y == 0:
        return float('nan')

    r = cov / math.sqrt(var_x * var_y)
    return max(-1.0, min(1.0, r))

