    encoded = [float(codes[g]) for g in grades]

    mean_x = sum(scores) / n
    mean_y = sum(encoded) / n

    cov = 0.0
    var_x = 0.0
    var_y = 0.0
    for x, y in zip(scores, encoded):
        dx = x - mean_x
        dy = y - mean_y
        cov += dx * dy
        var_x += dx * dx
        var_y += dy * dy

    if var_x == 0 or var_y == 0:
        return float('nan')

    r = cov / math.sqrt(var_x * var_y)
    return max(-1.0, min(1.0, r))

