import re
import math
from collections import Counter


def task_func(texts):
    url_pattern = re.compile(r'http[s]?://\S+')
    token_pattern = re.compile(r'(?u)\b\w\w+\b')

    cleaned = [url_pattern.sub('', text) for text in texts]
    tokenized = [token_pattern.findall(doc.lower()) for doc in cleaned]

    n_docs = len(tokenized)
    doc_freq = Counter()
    for tokens in tokenized:
        doc_freq.update(set(tokens))

    features = sorted(doc_freq)
    index = {word: i for i, word in enumerate(features)}
    idf = {
        word: math.log((1 + n_docs) / (1 + df)) + 1
        for word, df in doc_freq.items()
    }

    results = []
    for tokens in tokenized:
        row = [0.0] * len(features)
        for word, count in Counter(tokens).items():
            row[index[word]] = count * idf[word]
        norm = math.sqrt(sum(v * v for v in row))
        if norm > 0:
            row = [v / norm for v in row]
        results.append(tuple(round(v, 8) for v in row))

    return results, features

